CREATE TABLE IF NOT EXISTS subjects (id CHAR(36) PRIMARY KEY,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,category VARCHAR(64) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS grades (id CHAR(36) PRIMARY KEY,student_id CHAR(36) NOT NULL,subject_id CHAR(36) NOT NULL,academic_year VARCHAR(32) NOT NULL,semester VARCHAR(32) NOT NULL,assessment_type VARCHAR(64) NOT NULL,score DECIMAL(6,2) NULL,grade VARCHAR(16) NULL,teacher_note VARCHAR(1000) NULL,published BOOLEAN NOT NULL DEFAULT FALSE,teacher_user_id CHAR(36) NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX idx_grade_student(student_id,academic_year,semester),CONSTRAINT fk_grade_subject FOREIGN KEY(subject_id) REFERENCES subjects(id));
CREATE TABLE IF NOT EXISTS reports (id CHAR(36) PRIMARY KEY,student_id CHAR(36) NOT NULL,academic_year VARCHAR(32) NOT NULL,semester VARCHAR(32) NOT NULL,report_type VARCHAR(64) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'DRAFT',pdf_object_key VARCHAR(512) NULL,published_at DATETIME(6) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX idx_report_student(student_id,status));
